data.named.conf:
include "/etc/bind/named.conf.options";

include "/etc/bind/keys/rndc.key";

controls {
    inet 127.0.0.1 port 9530 allow { localhost; } keys { "bindy-operator"; };
};

logging {
    channel "default_stderr" {
        stderr;
        severity info;
        print-time iso8601;
        print-severity yes;
        print-category yes;
    };
    channel "queries_stderr" {
        stderr;
        severity info;
        print-time iso8601;
        print-severity yes;
        print-category yes;
    };
    channel "security_stderr" {
        stderr;
        severity warning;
        print-time iso8601;
        print-severity yes;
        print-category yes;
    };
    category "default" {
        "default_stderr";
    };
    category "general" {
        "default_stderr";
    };
    category "config" {
        "default_stderr";
    };
    category "network" {
        "default_stderr";
    };
    category "queries" {
        "queries_stderr";
    };
    category "security" {
        "security_stderr";
    };
    category "dnssec" {
        "security_stderr";
    };
    category "xfer-in" {
        "default_stderr";
    };
    category "xfer-out" {
        "default_stderr";
    };
    category "notify" {
        "default_stderr";
    };
    category "update" {
        "default_stderr";
    };
    category "update-security" {
        "security_stderr";
    };
};

data.named.conf.options:
options {
    directory "/var/cache/bind";
    dump-file "/var/cache/bind/cache_dump.db";
    statistics-file "/var/cache/bind/named_stats.txt";
    memstatistics-file "/var/cache/bind/named_mem_stats.txt";
    pid-file "/var/cache/bind/named.pid";
    session-keyfile "/var/cache/bind/session.key";
    key-directory "/var/cache/bind/keys";
    listen-on port 5353 { any; };
    listen-on-v6 port 5353 { any; };
    forwarders {
        192.0.2.53;
    };
    allow-query { 127.0.0.1; 198.51.100.0/24; 203.0.113.0/24; 192.0.2.0/25; };
    allow-transfer { none; };
    recursion yes;
    allow-new-zones yes;
    dnssec-validation auto;
    rate-limit {
        responses-per-second 15;
    };
};

dnssec-policy "example-dns" {
    keys {
        ksk lifetime unlimited algorithm ECDSAP256SHA256;
        zsk lifetime unlimited algorithm ECDSAP256SHA256;
    };
    max-zone-ttl 86400;
    nsec3param iterations 0 optout no salt-length 16;
    parent-propagation-delay 3600;
    signatures-refresh 5d;
    signatures-validity 30d;
    signatures-validity-dnskey 30d;
    zone-propagation-delay 300;
};

data.rndc.conf:
# RNDC client configuration for bindy operator
# This file is used by the 'rndc' command-line tool to connect to BIND9
# Key file is mounted from Secret at /etc/bind/keys/rndc.key

include "/etc/bind/keys/rndc.key";

# Default options for RNDC client
# Using 127.0.0.1 to connect to local BIND9 instance within the same pod
options {
    default-server 127.0.0.1;
    default-port 9530;
    default-key "bindy-operator";
};

# Server configuration - connects to BIND9 on localhost within the pod
server 127.0.0.1 {
    key "bindy-operator";
    port 9530;
};
